<?php
/** Proof — the webhook (spec "Proof", 1): a signed notice makes a ticket from the stub's message; the same notice again makes no second ticket; a bad signature, an old timestamp, an unknown address → 403 and nothing; GET → 405; source webhook on every row. */
require __DIR__ . '/lib.php';
$W = world();
$owner = as_member(1);
$mb = ensure_mailbox();
ok($mb > 0 && find_mailbox(pdo(), $mb)['secret_set'] === true, 'the IT mailbox exists and its webhook secret key is set');
put_mail(1, ['from' => 'New Person <New@Customer.invalid>', 'subject' => 'Printer jams on floor 3', 'cc' => 'colleague@customer.invalid'], "Hello,\n\nThe printer on floor 3 jams every morning.\n\nThanks,\nNew", ['attachments' => [['name' => 'jam.txt', 'content_type' => 'text/plain', 'content_base64' => base64_encode('SMOKE jam log')]]]);
echo "1. A signed notice\n";
$since = last_activity_id();
$tickets = (int) one('SELECT count(*) FROM tickets');
ok(webhook(1) === 204, 'the notice → 204');
$row = inbound_row(1);
ok($row !== null && $row['status'] === 'processed' && $row['ticket_id'] !== null && $row['message_ref_id'] !== null && $row['from_address'] === 'new@customer.invalid' && $row['message_id'] === '<mail-1@customer.invalid>', 'the inbound row: processed, linked to the ticket and the message, the headers kept' . ($row !== null && $row['status'] !== 'processed' ? ' (' . $row['status'] . ': ' . $row['error'] . ')' : ''));
$t = (int) $row['ticket_id'];
$tr = ticket_row($t);
$req = q('SELECT kind, display_name, primary_email::text AS e, organization_id FROM requesters WHERE id = :r', ['r' => (int) $tr['requester_id']])[0];
ok((int) one('SELECT count(*) FROM tickets') === $tickets + 1 && $tr['channel'] === 'email' && $tr['subject'] === 'Printer jams on floor 3' && (int) $tr['queue_id'] === $W['it'] && $tr['created_by'] === null, 'one ticket: channel email, the subject, the mailbox\'s queue');
ok($req['kind'] === 'external' && $req['e'] === 'new@customer.invalid' && $req['display_name'] === 'New Person' && (int) $req['organization_id'] === $W['org'], 'the requester: external, named from the From, claimed by the domain');
$m = q('SELECT kind, channel, body_text, email_message_id, author_requester_id FROM messages WHERE ticket_id = :t ORDER BY id', ['t' => $t]);
ok(count($m) === 1 && $m[0]['kind'] === 'public_reply' && $m[0]['channel'] === 'email' && $m[0]['email_message_id'] === '<mail-1@customer.invalid>' && $m[0]['body_text'] === "Hello,\n\nThe printer on floor 3 jams every morning.\n\nThanks,\nNew" && (int) $m[0]['author_requester_id'] === (int) $tr['requester_id'], 'the body as the first public reply with its Message-ID');
ok((int) one('SELECT count(*) FROM attachments WHERE ticket_id = :t AND message_id IS NOT NULL', ['t' => $t]) === 1 && (int) one("SELECT count(*) FROM ticket_followers WHERE ticket_id = :t AND kind = 'cc'", ['t' => $t]) === 1, 'the attachment on the message; the Cc a follower');
ok((int) one('SELECT count(*) FROM ticket_links_secure WHERE ticket_id = :t AND rotated_at IS NULL', ['t' => $t]) === 1 && count(outbox($t, 'created')) === 1 && preg_match('#/t/[a-f0-9]{48}#', outbox($t, 'created')[0]['body']) === 1, 'the link minted; the created notice carries it');
$calls = array_map(fn ($c) => $c['tool'] . ':' . ($c['args']['uid'] ?? ''), mcp_calls());
ok(in_array('read_message:1', $calls, true) && in_array('mark_message:1', $calls, true) && in_array('\\Seen', mail_flags(1), true), 'read through the MCP and marked seen');
$rows = q('SELECT action, source FROM activity_log WHERE id > :s AND action IN (\'ticket.create\', \'mail.inbound\')', ['s' => $since]);
ok(count($rows) === 2 && count(array_filter($rows, fn ($r) => $r['source'] === 'webhook')) === 2, 'ticket.create and mail.inbound logged with source webhook');
echo "2. Idempotent, and the refusals\n";
ok(webhook(1) === 204 && (int) one('SELECT count(*) FROM tickets') === $tickets + 1 && (int) one('SELECT count(*) FROM inbound_email WHERE provider_uid = :u', ['u' => '1']) === 1, 'the same notice again: 204 and no second ticket');
put_mail(2, ['from' => 'Other <other@customer.invalid>', 'subject' => 'Second'], 'x');
$n = (int) one('SELECT count(*) FROM inbound_email');
ok(webhook(2, 'wrong-secret') === 403 && (int) one('SELECT count(*) FROM inbound_email') === $n, 'a bad signature: 403, nothing written');
ok(webhook(2, null, time() - 360) === 403 && (int) one('SELECT count(*) FROM inbound_email') === $n, 'a six-minute-old timestamp: 403');
ok(webhook(2, null, null, 'nobody@example.invalid') === 403 && (int) one('SELECT count(*) FROM inbound_email') === $n, 'an unknown address: 403');
ok(webhook(2, null, null, MAILBOX_ADDRESS, 'GET') === 405, 'GET: 405');
ok(webhook(2, null, null, MAILBOX_ADDRESS, 'POST', ['type' => 'message.flags']) === 204 && (int) one('SELECT count(*) FROM inbound_email') === $n, 'another event type: 204, nothing read');
ok(webhook(2) === 204 && inbound_row(2)['status'] === 'processed', 'the right notice: processed');
file_put_contents(need('HD_DEV_STATE') . '/slice7.json', json_encode(['ticket' => $t, 'requester' => (int) $tr['requester_id']]));
finish();
